css:
[data-bz-node="hero-slides"]{position:relative;min-height:calc(730 * var(--u));background:#111;gap:0;overflow:hidden}
[data-bz-node="hero-slides"] [data-bz-part="slide"]{background-size:cover;background-position:center;background-color:#111}
[data-bz-node="hero-slides"] .bz-col,[data-bz-node="hero-slides"] .bz-block{margin:0;padding:0}
[data-bz-node="hero-slides"] img{display:block;width:100%;height:calc(730 * var(--u));object-fit:contain}
/* Before the script runs (and in the Design canvas) only the first image shows, in flow. */
[data-bz-node="hero-slides"]:not(.is-staged) [data-bz-part="slide"]:not(:first-child){display:none}
/* Staged: every image stacked, each cross-fading on its own delay, like the live site. */
[data-bz-node="hero-slides"].is-staged [data-bz-part="slide"]{position:absolute;inset:0;opacity:0;animation:hero-fade var(--hero-total) linear infinite both}
[data-bz-node="hero-slides"].is-staged [data-bz-part="slide"] img{height:100%}
[data-bz-node="hero-slides"] .bz-block,[data-bz-node="hero-slides"] .bz-container,[data-bz-node="hero-slides"] .bz-figure{display:block;width:100%;max-width:none;height:calc(730 * var(--u));margin:0;padding:0}
[data-bz-node="hero-slides"].is-staged .bz-block,[data-bz-node="hero-slides"].is-staged .bz-container,[data-bz-node="hero-slides"].is-staged .bz-figure{height:100%}

js:
(function () {
  document.querySelectorAll('[data-bz-node="hero-slides"]').forEach(function (row) {
    var slides = row.querySelectorAll('[data-bz-part="slide"]');
    var n = slides.length;
    // Dark, enlarged copy of each photo fills the sides the photo itself does not reach.
    slides.forEach(function (slide) {
      var img = slide.querySelector('img');
      if (!img) return;
      var src = img.currentSrc || img.getAttribute('src');
      slide.style.backgroundImage = 'linear-gradient(rgba(0,0,0,.68),rgba(0,0,0,.68)), url("' + src + '")';
    });
    if (n < 2) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    var hold = 5, fade = 1.4, total = n * hold;
    function p(s) { return (s / total * 100).toFixed(3) + '%'; }
    var style = document.createElement('style');
    style.textContent = '@keyframes hero-fade{0%{opacity:0}' + p(fade) + '{opacity:1}' + p(hold) +
      '{opacity:1}' + p(hold + fade) + '{opacity:0}100%{opacity:0}}';
    document.head.appendChild(style);
    row.style.setProperty('--hero-total', total + 's');
    slides.forEach(function (slide, i) { slide.style.animationDelay = (i * hold) + 's'; });
    row.classList.add('is-staged');
  });
})();
